const SHEET='1aTyJN0KQRLuGt96aPSGGGV8I8-KVqQmhut07MVEvook';
export function parseUniversities(html){
  const decode=s=>s.replace(/&(#x[\da-f]+|#\d+|amp|quot|apos|lt|gt|nbsp);/gi,(_,entity)=>{
    if(entity[0]==='#'){const code=entity[1].toLowerCase()==='x'?parseInt(entity.slice(2),16):parseInt(entity.slice(1),10);return code<=0x10ffff?String.fromCodePoint(code):'';}
    return {amp:'&',quot:'"',apos:"'",lt:'<',gt:'>',nbsp:' '}[entity.toLowerCase()];
  });
  return [...new Set([...html.matchAll(/class="[^"]*\bdocs-sheet-tab-caption\b[^"]*"[^>]*>([^<]*)</g)].map(x=>decode(x[1]).trim()).filter(Boolean))];
}
export async function universityResponse(fetcher=fetch){
  try{
    const response=await fetcher(`https://docs.google.com/spreadsheets/d/${SHEET}/edit?_= ${Date.now()}`.replace('= ','='),{signal:AbortSignal.timeout(20000),headers:{'Cache-Control':'no-cache'}});
    if(!response.ok)throw new Error('The Google Sheet is not accessible. Keep its sharing set to Anyone with the link — Viewer.');
    const names=parseUniversities(await response.text());
    if(!names.length)throw new Error('No university tabs could be read from the Google Sheet. Please try again.');
    return Response.json(names,{headers:{'Cache-Control':'no-store'}});
  }catch(error){return Response.json({error:error.message||'Unable to read university tabs.'},{status:502,headers:{'Cache-Control':'no-store'}});}
}
export async function editorResponse(request,fetcher=fetch){
  const reply=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
  try{
    // Reject cross-origin form submissions; editor credentials only travel in JSON bodies.
    if(!request.headers.get('Content-Type')?.startsWith('application/json'))return reply({error:'JSON request required.'},415);
    const origin=request.headers.get('Origin');
    if(origin && origin!==new URL(request.url).origin)return reply({error:'Invalid request origin.'},403);
    const text=await request.text();if(text.length>1000000)return reply({error:'Request too large.'},413);
    const input=JSON.parse(text);
    if(!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(input.endpoint||''))return reply({error:'Enter a valid Google Apps Script deployment URL ending in /exec.'},400);
    if(typeof input.key!=='string'||input.key.length<32||input.key.length>512)return reply({error:'Enter your editor key (at least 32 characters).'},400);
    if(!['list','read','save','addUniversity','addPage','addField'].includes(input.action))return reply({error:'Invalid action.'},400);
    const {endpoint,...payload}=input;
    const response=await fetcher(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),redirect:'follow',signal:AbortSignal.timeout(60000)});
    if(!response.ok)return reply({error:'Google could not complete the request. Check the deployment access settings.'},502);
    let result;try{result=await response.json();}catch{return reply({error:'The connection did not return data. Deploy the script as a web app with access set to Anyone.'},502);}
    if(!result.ok)return reply({error:result.error||'Google Sheets rejected the request.'},400);
    if(result.spreadsheetId!==SHEET)return reply({error:'This editor is connected to a different spreadsheet.'},400);
    return reply(result);
  }catch{return reply({error:'Unable to confirm the Google Sheets request. Refresh data to check its result before trying again.'},502);}
}
export function createHandler(assets){return {async fetch(request){
  const pathname=new URL(request.url).pathname;
  if(pathname==='/api/editor'){
    if(request.method!=='POST')return new Response('Method not allowed',{status:405});
    return editorResponse(request);
  }
  if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});
  if(pathname==='/api/universities')return universityResponse();
  const asset=assets[pathname==='/'?'/index.html':pathname];
  if(!asset)return new Response('Not found',{status:404});
  return new Response(request.method==='HEAD'?null:asset.content,{headers:{'Content-Type':asset.type,'Cache-Control':'no-cache'}});
}};}

export default createHandler({"/index.html":{"content":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>University Meta Explorer</title><meta name=\"description\" content=\"Browse university page metadata from Google Sheets.\"><link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%23163663'/%3E%3Cpath d='M5 12l11-6 11 6-11 6zM9 17v7h14v-7' fill='none' stroke='white' stroke-width='2'/%3E%3C/svg%3E\"><link rel=\"stylesheet\" href=\"style.css\"><script src=\"app.js\" defer></script></head>\n<body><header><a class=\"brand\" href=\"#\"><span class=\"mark\" aria-hidden=\"true\">U</span>University Meta <span class=\"brand-sub\">EXPLORER</span></a><button id=\"connect-editor\" class=\"secondary\">Connect editor</button><a class=\"source\" href=\"https://docs.google.com/spreadsheets/d/1aTyJN0KQRLuGt96aPSGGGV8I8-KVqQmhut07MVEvook/edit\" target=\"_blank\" rel=\"noopener\">Open Google Sheet</a></header>\n<main><section id=\"selection\"><div class=\"step\">01 / SELECT UNIVERSITY</div><h1>Choose your university.</h1><p class=\"intro\">View the page metadata saved in your Google Sheet.</p><form id=\"university-form\" class=\"select-card\"><label for=\"university\">University</label><select id=\"university\" required disabled><option value=\"\">Loading universities…</option></select><p class=\"hint\" id=\"count\">Loading the university directory.</p><button id=\"submit\" type=\"submit\" disabled>Submit</button></form><div class=\"toolbar\"><button id=\"add-university\" class=\"secondary\" disabled>Add university</button><button id=\"refresh-universities\" class=\"secondary\">Refresh universities</button></div><div id=\"directory-error\" role=\"alert\"></div><p class=\"footnote\">Select a university, then choose a page to view its entries.</p></section>\n<section id=\"details\" hidden><button class=\"back\" id=\"back\">Change university</button><div class=\"step\">02 / PAGE METADATA</div><h1 id=\"university-title\"></h1><p class=\"intro\">Choose a page to view its entries.</p><div class=\"workspace\"><nav aria-label=\"University pages\"><div class=\"nav-label\">PAGES</div><div id=\"pages\"></div><button id=\"add-page\" class=\"secondary\" disabled>Add page</button></nav><article><div class=\"article-head\"><div><span class=\"eyebrow\">SELECTED PAGE</span><h2 id=\"page-title\">Loading…</h2></div><button id=\"refresh\" class=\"secondary\">Refresh data</button></div><div id=\"status\" role=\"status\" aria-live=\"polite\"></div><form id=\"metadata-form\"><div id=\"metadata\"></div><div class=\"toolbar\"><button id=\"save\" type=\"submit\" hidden>Save to Google Sheet</button><button id=\"add-field\" type=\"button\" class=\"secondary\" disabled>Add field</button></div></form></article></div><p class=\"footnote\" id=\"updated\"></p></section></main><dialog id=\"connection-dialog\"><form id=\"connection-form\"><h2>Connect Google Sheet editor</h2><p>Use the web app URL and editor key from the one-time Google setup.</p><label for=\"endpoint\">Google Apps Script web app URL</label><input id=\"endpoint\" type=\"url\" required placeholder=\"https://script.google.com/macros/s/…/exec\"><label for=\"editor-key\">Editor key</label><input id=\"editor-key\" type=\"password\" required minlength=\"32\" autocomplete=\"off\"><p class=\"hint\">The key stays in memory until you disconnect or reload this page.</p><div id=\"connection-status\" role=\"status\" aria-live=\"polite\"></div><div class=\"toolbar\"><button id=\"connection-submit\" type=\"submit\">Connect</button><button type=\"button\" class=\"secondary\" id=\"connection-cancel\">Cancel</button></div></form></dialog><dialog id=\"add-dialog\"><form id=\"add-form\"><h2 id=\"add-title\">Add page</h2><label for=\"new-name\" id=\"name-label\">Page name</label><input id=\"new-name\" required maxlength=\"200\"><p id=\"add-help\" class=\"hint\"></p><div id=\"add-status\" role=\"status\" aria-live=\"polite\"></div><div class=\"toolbar\"><button id=\"add-submit\" type=\"submit\">Add to Google Sheet</button><button id=\"add-cancel\" type=\"button\" class=\"secondary\">Cancel</button></div></form></dialog><footer>University Meta Explorer <span id=\"editor-state\">Viewer mode</span></footer></body></html>\n\r\n","type":"text/html; charset=utf-8"},"/app.js":{"content":"const SHEET='1aTyJN0KQRLuGt96aPSGGGV8I8-KVqQmhut07MVEvook';\nconst $=id=>document.getElementById(id);\nlet universities=[],snapshot=null,activeUniversity='',activePage='',requestNumber=0,editor=null,dirty=false,busy=false,currentHash='',addAction='';\nconst text=c=>String(c?.f??c?.v??'');\nfunction readSheet(name){return new Promise((resolve,reject)=>{\n  const callback='sheetResponse'+Date.now()+Math.random().toString(36).slice(2),script=document.createElement('script');let timer;\n  function clean(){clearTimeout(timer);script.remove();delete window[callback];}\n  window[callback]=data=>{clean();if(data.status!=='ok'||!data.table)return reject(Error('The sheet could not be read.'));\n    const fields=data.table.cols.map((c,index)=>({column:index+1,label:c.label?.trim()})).filter(f=>f.column>1&&f.label);\n    const rows=data.table.rows.map((r,index)=>({row:index+2,page:text(r.c[0]).trim(),values:Object.fromEntries(fields.map(f=>[f.column,text(r.c[f.column-1])]))})).filter(r=>r.page);\n    resolve({university:name,fields,rows});\n  };\n  script.onerror=()=>{clean();reject(Error('Unable to connect to Google Sheets.'));};\n  timer=setTimeout(()=>{clean();reject(Error('Google Sheets took too long to respond.'));},20000);\n  const q=new URLSearchParams({sheet:name,headers:'1',tqx:'out:json;responseHandler:'+callback,_:Date.now()});\n  script.src=`https://docs.google.com/spreadsheets/d/${SHEET}/gviz/tq?${q}`;document.head.append(script);\n});}\nasync function editorRequest(action,extra={},credentials=editor){\n  if(!credentials)throw Error('Connect the editor first.');\n  const response=await fetch('/api/editor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...extra,...credentials,action}),signal:AbortSignal.timeout(70000)});\n  const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Unable to confirm the change. Refresh data to check the result.');return result;\n}\nfunction status(message,error=false){$('status').textContent=message;$('status').className=error?'error':'';}\nfunction controls(){\n  for(const id of ['back','refresh','refresh-universities','connect-editor','submit','university'])$(id).disabled=busy;\n  for(const id of ['add-university','add-page','add-field'])$(id).disabled=busy||!editor||(id!=='add-university'&&!snapshot);\n  $('save').hidden=!editor||!snapshot?.rows.length;$('save').disabled=busy||!dirty;\n  for(const button of $('pages').children)button.disabled=busy;\n  for(const input of $('metadata').querySelectorAll('textarea'))input.disabled=busy;\n  $('editor-state').textContent=editor?'Editor connected':'Viewer mode';$('connect-editor').textContent=editor?'Disconnect editor':'Connect editor';\n}\nfunction discard(){if(busy)return false;if(dirty&&!confirm('Discard your unsaved changes?'))return false;dirty=false;return true;}\nfunction route(name,page){if(!discard())return;const q=new URLSearchParams();if(name)q.set('university',name);if(page)q.set('page',page);location.hash=q.toString();}\nfunction showRow(page){\n  activePage=page;dirty=false;const row=snapshot.rows.find(r=>r.page===page);$('page-title').textContent=page;$('metadata').replaceChildren();\n  for(const field of snapshot.fields){const div=document.createElement('section');div.className='field';const label=document.createElement(editor?'label':'h3');label.textContent=field.label==='Meta Decription'?'Meta Description':field.label;\n    const value=editor?document.createElement('textarea'):document.createElement('p');\n    if(editor){value.id='field-'+field.column;label.htmlFor=value.id;value.dataset.column=field.column;value.value=row?.values[field.column]||'';value.rows=field.label.toLowerCase().includes('title')?2:4;value.maxLength=50000;value.oninput=()=>{dirty=snapshot.fields.some(f=>$('field-'+f.column).value!==(row.values[f.column]||''));status(dirty?'Unsaved changes.':'');controls();};}\n    else{value.className='value';value.textContent=row?.values[field.column]||'Not added yet';if(!row?.values[field.column])value.classList.add('empty');}\n    div.append(label,value);$('metadata').append(div);\n  }\n  if(!snapshot.fields.length){const p=document.createElement('p');p.textContent='No metadata fields yet. Connect the editor and select Add field.';$('metadata').append(p);}\n  for(const b of $('pages').children)b.setAttribute('aria-current',b.textContent===page?'page':'false');controls();\n}\nfunction applySnapshot(data,wantedPage){snapshot=data;$('pages').replaceChildren();for(const row of data.rows){const b=document.createElement('button');b.textContent=row.page;b.onclick=()=>route(activeUniversity,row.page);$('pages').append(b);}\n  if(data.rows.length)showRow(data.rows.some(r=>r.page===wantedPage)?wantedPage:data.rows[0].page);else{activePage='';$('page-title').textContent='No pages yet';$('metadata').replaceChildren();dirty=false;controls();}\n  $('updated').textContent='Last fetched at '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'. '+(editor?'Changes are saved only when you select Save to Google Sheet.':'Connect the editor to change values.');\n}\nasync function load(name,wantedPage){\n  const token=++requestNumber;snapshot=null;busy=true;$('metadata').replaceChildren();$('pages').replaceChildren();$('page-title').textContent='Loading pages…';status('Reading the latest entries from Google Sheets…');controls();\n  try{const data=editor?await editorRequest('read',{university:name}):await readSheet(name);if(token!==requestNumber)return;applySnapshot(data,wantedPage);status('');}\n  catch(error){if(token!==requestNumber)return;$('page-title').textContent='Unable to load entries';status(error.message,true);}\n  finally{if(token===requestNumber){busy=false;controls();}}\n}\nfunction renderRoute(){\n  if(location.hash!==currentHash&&(busy||dirty)){if(!discard()){history.replaceState(null,'',currentHash||location.pathname);return;}}\n  currentHash=location.hash;const q=new URLSearchParams(location.hash.slice(1)),name=q.get('university'),page=q.get('page');\n  if(!name){requestNumber++;activeUniversity='';snapshot=null;$('selection').hidden=false;$('details').hidden=true;document.title='University Meta Explorer';controls();return;}\n  if(!universities.includes(name)){location.hash='';return;}\n  $('selection').hidden=true;$('details').hidden=false;$('university-title').textContent=name;document.title=name+' · University Meta Explorer';\n  if(name!==activeUniversity||!snapshot){activeUniversity=name;load(name,page);}else if(snapshot.rows.length)showRow(snapshot.rows.some(r=>r.page===page)?page:snapshot.rows[0].page);\n}\nfunction fillUniversities(data){universities=data;const selected=$('university').value;$('university').replaceChildren(new Option('Select a university',''));for(const name of data)$('university').add(new Option(name,name));if(data.includes(selected))$('university').value=selected;$('count').textContent=data.length+' universities available · Updated from Google Sheets';}\nasync function loadUniversities(){\n  $('directory-error').textContent='';$('refresh-universities').disabled=true;\n  try{let data;if(editor)data=(await editorRequest('list')).universities;else{const r=await fetch('/api/universities',{cache:'no-store',signal:AbortSignal.timeout(25000)});data=await r.json();if(!r.ok)throw Error(data.error||'Unable to read university tabs.');}if(!Array.isArray(data))throw Error('Unable to read university tabs.');fillUniversities(data);renderRoute();}\n  catch(error){$('directory-error').textContent=error.message+' Reload the page to try again.';}\n  finally{controls();if(!universities.length){$('university').disabled=true;$('submit').disabled=true;}}\n}\n$('university-form').onsubmit=e=>{e.preventDefault();if($('university').value)route($('university').value);};\n$('back').onclick=()=>route();$('refresh').onclick=()=>{if(discard())load(activeUniversity,activePage);};$('refresh-universities').onclick=()=>{if(discard())loadUniversities();};\nwindow.addEventListener('hashchange',renderRoute);window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});\n$('connect-editor').onclick=async()=>{if(!discard())return;if(editor){editor=null;requestNumber++;busy=false;if(activeUniversity)await load(activeUniversity,activePage);controls();}else{$('connection-status').textContent='';$('connection-dialog').showModal();}};\n$('connection-cancel').onclick=()=>{$('connection-dialog').close();$('editor-key').value='';};\n$('connection-dialog').addEventListener('close',()=>{$('editor-key').value='';});\n$('connection-form').onsubmit=async e=>{e.preventDefault();const credentials={endpoint:$('endpoint').value.trim(),key:$('editor-key').value};$('connection-submit').disabled=true;$('connection-cancel').disabled=true;$('connection-status').textContent='Checking your connection…';\n  try{const result=await editorRequest('list',{},credentials);editor=credentials;fillUniversities(result.universities);$('connection-dialog').close();if(activeUniversity)await load(activeUniversity,activePage);controls();}\n  catch(error){$('connection-status').textContent=error.message;}\n  finally{$('connection-submit').disabled=false;$('connection-cancel').disabled=false;}\n};\n$('metadata-form').onsubmit=async e=>{e.preventDefault();if(!editor||!dirty||busy)return;const row=snapshot.rows.find(r=>r.page===activePage),values={};for(const f of snapshot.fields){const value=$('field-'+f.column).value;if(value!==row.values[f.column])values[f.column]=value;}\n  busy=true;status('Saving to Google Sheets…');controls();\n  try{const data=await editorRequest('save',{university:activeUniversity,row:row.row,page:row.page,version:snapshot.version,values});applySnapshot(data,activePage);status('Saved to Google Sheets.');}\n  catch(error){status(error.message,true);}\n  finally{busy=false;controls();}\n};\nfunction openAdd(action){if(!editor||!discard())return;addAction=action;const item=action==='addUniversity'?'university':action==='addPage'?'page':'field';$('add-title').textContent='Add '+item;$('name-label').textContent=item[0].toUpperCase()+item.slice(1)+' name';$('new-name').value='';$('new-name').maxLength=action==='addUniversity'?100:200;$('add-status').textContent='';$('add-help').textContent=action==='addUniversity'?'Creates a university tab with the standard pages and metadata fields.':action==='addPage'?'Adds a page option to this university. You can enter its metadata next.':'Adds a metadata column for every page in this university.';$('add-dialog').showModal();}\n$('add-university').onclick=()=>openAdd('addUniversity');$('add-page').onclick=()=>openAdd('addPage');$('add-field').onclick=()=>openAdd('addField');$('add-cancel').onclick=()=>$('add-dialog').close();\n$('add-dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();});\n$('connection-dialog').addEventListener('cancel',e=>{if($('connection-submit').disabled)e.preventDefault();});\n$('add-form').onsubmit=async e=>{e.preventDefault();const name=$('new-name').value.trim();$('add-submit').disabled=true;$('add-cancel').disabled=true;busy=true;controls();$('add-status').textContent='Adding to Google Sheets…';\n  try{const data=await editorRequest(addAction,{name,university:activeUniversity,version:snapshot?.version});\n    if(addAction==='addUniversity'){fillUniversities((await editorRequest('list')).universities);activeUniversity=data.university;applySnapshot(data);const q=new URLSearchParams({university:activeUniversity});history.replaceState(null,'','#'+q);currentHash=location.hash;$('selection').hidden=true;$('details').hidden=false;$('university-title').textContent=activeUniversity;document.title=activeUniversity+' · University Meta Explorer';}\n    else{applySnapshot(data,addAction==='addPage'?name:activePage);const q=new URLSearchParams({university:activeUniversity,page:activePage});history.replaceState(null,'','#'+q);currentHash=location.hash;}\n    $('add-dialog').close();status('Added to Google Sheets. You can now enter the details.');\n  }catch(error){$('add-status').textContent=error.message;}\n  finally{busy=false;controls();$('add-submit').disabled=false;$('add-cancel').disabled=false;}\n};\ncontrols();loadUniversities();\r\n","type":"text/javascript; charset=utf-8"},"/style.css":{"content":":root{font-family:Inter,Segoe UI,Arial,sans-serif;color:#182d49;background:#f5f7fb;font-synthesis:none}*{box-sizing:border-box}body{margin:0}header{min-height:88px;padding:20px 5%;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #dfe5ee;background:white;gap:20px}a{color:inherit;text-decoration:none}.brand{display:flex;align-items:center;gap:12px;font-size:18px;font-weight:700}.mark{display:grid;place-items:center;width:38px;height:38px;background:#163663;color:white;border-radius:9px;font-family:Georgia,serif;font-size:27px}.brand-sub{font-size:12px;letter-spacing:1.5px;font-weight:600;color:#6c7b90;border-left:1px solid #dfe5ee;padding-left:12px}.source{font-size:14px;color:#425c7e;text-decoration:underline;text-underline-offset:4px}main{max-width:1240px;margin:auto;padding:65px 40px;min-height:calc(100vh - 157px)}#selection{max-width:640px;margin:30px auto}.step{font-size:12px;letter-spacing:1.8px;font-weight:700;color:#4f6e96;margin-bottom:19px}h1{font-size:clamp(28px,4vw,42px);line-height:1.2;letter-spacing:-1px;margin:0 0 16px;font-weight:650}.intro{font-size:16px;color:#627188;line-height:1.6;margin:0 0 32px}.select-card{background:white;border:1px solid #dce3ee;border-radius:14px;padding:32px;box-shadow:0 12px 30px #15375e08}label{display:block;font-size:14px;font-weight:650;margin-bottom:12px}select{width:100%;padding:16px 14px;font:inherit;font-size:16px;border:1px solid #b9c7d9;border-radius:7px;color:#182d49;background:#fff}.hint,.footnote{font-size:14px;color:#728197;line-height:1.6}.hint{margin:13px 0 27px}button{cursor:pointer;font:inherit;font-size:14px;font-weight:600;border:0;border-radius:7px;padding:13px 20px;background:#163663;color:white}button:hover{background:#254c7f}button:disabled{opacity:.5;cursor:wait}#submit{width:100%;font-size:16px}.footnote{margin-top:23px}.back{background:transparent;color:#425c7e;padding:0;margin-bottom:30px;text-decoration:underline;text-underline-offset:4px}.back:hover{background:transparent;color:#163663}#details h1{max-width:950px;font-size:32px}.workspace{display:grid;grid-template-columns:255px 1fr;background:#fff;border:1px solid #dce3ee;border-radius:12px;overflow:hidden;min-height:430px}nav{background:#f9fbfe;border-right:1px solid #dce3ee;padding:25px 16px}.nav-label{font-size:12px;letter-spacing:1.5px;color:#738197;font-weight:700;padding:0 12px 20px}#pages button{display:block;text-align:left;width:100%;background:transparent;color:#53647b;margin-bottom:5px;padding:13px 12px;font-weight:500;line-height:1.4}#pages button:hover{background:#eaf0f8}#pages button[aria-current=\"page\"]{background:#163663;color:#fff;font-weight:600}article{padding:30px;min-width:0}.article-head{display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:1px solid #e4e9f0;padding-bottom:24px;margin-bottom:24px}.eyebrow{font-size:12px;letter-spacing:1.5px;color:#728197}h2{font-size:23px;margin:8px 0 0}.secondary{color:#425c7e;background:white;border:1px solid #ced8e6;white-space:nowrap}.secondary:hover{background:#f4f7fb}.field{margin-bottom:27px}.field h3{font-size:14px;font-weight:650;color:#5d6f87;margin:0 0 10px}.value{font-size:16px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.empty{color:#8995a6;font-style:italic}#status:not(:empty),#directory-error:not(:empty){background:#f1f5fc;border-radius:7px;padding:16px;font-size:14px;line-height:1.6;margin-bottom:20px}#status.error,#directory-error{color:#a43a35}footer{padding:23px 5%;border-top:1px solid #dfe5ee;font-size:12px;color:#728197;display:flex;justify-content:space-between}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #619ae8;outline-offset:4px}[hidden]{display:none!important}@media(max-width:740px){header{padding:18px 22px}.brand-sub{display:none}.brand{font-size:15px}.source{font-size:12px}main{padding:36px 20px}#selection{margin:15px auto}.select-card{padding:24px}.workspace{grid-template-columns:1fr}nav{border-right:0;border-bottom:1px solid #dce3ee;padding:20px 16px}#pages{display:flex;flex-wrap:wrap;gap:5px}#pages button{width:auto;margin:0;font-size:14px}.nav-label{padding-bottom:12px}article{padding:24px 20px}.article-head{align-items:flex-start;flex-wrap:wrap}#details h1{font-size:27px}footer{gap:20px}}\n.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:20px}input,textarea{display:block;width:100%;border:1px solid #b9c7d9;border-radius:7px;padding:12px;font:inherit;color:#182d49;background:#fff}textarea{resize:vertical;min-height:75px;line-height:1.6}.field label{color:#5d6f87}dialog{width:min(560px,calc(100% - 32px));padding:28px;border:1px solid #dce3ee;border-radius:12px;color:#182d49;max-height:90vh}dialog::backdrop{background:#132a4a80}dialog p{font-size:14px;line-height:1.6;color:#627188}dialog h2{margin-bottom:24px}dialog label{margin:20px 0 10px}#connection-status,#add-status{font-size:14px;line-height:1.6;color:#a43a35}nav>.secondary{margin:15px 12px 0}textarea:focus-visible,input:focus-visible{outline:3px solid #619ae8;outline-offset:2px}#save:disabled{cursor:default}@media(max-width:740px){header{flex-wrap:wrap}.toolbar button{flex:1}dialog{padding:22px}}\r\n","type":"text/css; charset=utf-8"}})